ug'=>'video']];\App\Models\Setting::updateOrCreate(['key'=>'home_menu'],['value'=>json_encode($menu,JSON_UNESCAPED_UNICODE),'type'=>'json','is_public'=>true]); $samples=[['doctor','ডাক্তার সেবা','ডাক্তারদের তথ্য ও চেম্বার খুঁজুন'],['hospital','হাসপাতাল','ফেনীর হাসপাতাল ও চিকিৎসা প্রতিষ্ঠান'],['hotel','হোটেল নাইট হোল্ড','মহিপাল, ফেনী'],['restaurant','ইস্টিশন রেস্টুরেন্ট এন্ড কনভেনশন','SSK Road, Feni'],['job','সেলসম্যান','একটি স্বনামধন্য সুপার শপ'],['tourist_place','প্রতাপপুর জমিদার বাড়ি','প্রতাপপুর, দাগনভূঞা, ফেনী'],['video','ফেনী জেলার ভিডিও','https://www.youtube.com/watch?v=tNgXGowqSHc']]; $pageSeeds=[['about','আমাদের সম্পর্কে','Feni City সম্পর্কে তথ্য Admin Panel থেকে এখানে প্রকাশ করা যাবে।'],['contact','যোগাযোগ','Feni City-এর যোগাযোগের তথ্য Admin Panel থেকে এখানে প্রকাশ করা যাবে।'],['privacy-policy','Privacy Policy','Privacy policy content is controlled from the Admin Panel.'],['terms','Terms & Conditions','Terms and conditions content is controlled from the Admin Panel.']]; foreach($pageSeeds as [$slug,$title,$body]){ContentItem::firstOrCreate(['slug'=>$slug],['type'=>'page','title'=>$title,'excerpt'=>$body,'body'=>$body,'status'=>'published','created_by'=>$admin->id,'updated_by'=>$admin->id,'published_by'=>$admin->id,'published_at'=>now()]);} $externalCategories=[['name'=>'Blood','slug'=>'blood'],['name'=>'Bus','slug'=>'bus'],['name'=>'Train','slug'=>'train'],['name'=>'Website','slug'=>'website']]; foreach($externalCategories as $cat){\App\Models\Category::firstOrCreate(['slug'=>$cat['slug']],['name'=>$cat['name'],'status'=>'active']);} foreach($samples as [$type,$title,$body]){$item=ContentItem::firstOrCreate(['slug'=>Str::slug($title)],['type'=>$type,'title'=>$title,'body'=>$body,'status'=>'published','created_by'=>$admin->id,'updated_by'=>$admin->id,'published_by'=>$admin->id,'published_at'=>now()]);$loc=Location::firstOrCreate(['address'=>$body],['district'=>'Feni']);$item->update(['location_id'=>$loc->id]);}}}
